// provideRepoSandboxRunner builds the git-worktree sandbox (biz.RepoSandbox)
// anchored at sandbox.repo_root (fallback: process working directory — the
// admin must then be started from the repository root when self-improvement
// is enabled, gray-rollout feature). Gate timeouts/worktree root come from
// config (D4).
func provideRepoSandboxRunner(siConf *conf.SelfImprovement, lg loggateway.Logger) *service.RepoSandboxRunner {
	if !siConf.SIEnabled() {
		return nil
	}
	repoRoot := siConf.SIRepoRoot()
	if repoRoot == "" {
		wd, err := os.Getwd()
		if err != nil {
			lg.Warn("self-improve sandbox: resolve repo root failed, pipeline disabled", loggateway.StepID("si_sandbox.init"), loggateway.Err(err))
			return nil
		}
		repoRoot = wd
	}
	timeouts := siConf.SIGateTimeouts()
	runner, err := service.NewRepoSandboxRunner(repoRoot, lg, service.WithWorktreeRoot(siConf.SIWorktreeRoot()), service.WithGateTimeout(biz.SandboxGateBuild, timeouts["g1"]), service.WithGateTimeout(biz.SandboxGateTest, timeouts["g2"]), service.WithGateTimeout(biz.SandboxGateLint, timeouts["g3"]))
	if err != nil {
		lg.Warn("self-improve sandbox init failed, pipeline disabled", loggateway.StepID("si_sandbox.init"), loggateway.Err(err))
		return nil
	}
	return runner
}

